<?php require __DIR__.'/bootstrap.php';$u=uid();$id=(int)($_GET['id']??0);$a=q('SELECT * FROM mn_attachments WHERE id=? AND user_id=?',[$id,$u])->fetch();if(!$a){http_response_code(404);exit;} $file=__DIR__.'/storage/'.$a['stored_name'];if(!is_file($file)){http_response_code(404);exit;}header('Content-Type: '.$a['mime']);header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'_',basename($a['original_name'])).'"');header('Content-Length: '.filesize($file));readfile($file);
